<script setup lang="ts">
import { apiError } from '~/composables/useApi'
import { usableGrant,grantLimits,canPowerResource,isRunPending,canRedrive,canAcknowledge,actionConfirmation } from '~/composables/connectorLifecycle'
import type { LifecycleTarget,LifecycleBinding,ServiceGrant,ConnectorRun,WebhookSource,ConnectorEvent,ConnectorAction,LifecycleResource,CollectorDefinition,CollectionJobPlan } from '~/composables/connectorLifecycle'
const props=defineProps<{target:LifecycleTarget;binding:LifecycleBinding|null;operations:string[];collectors?:CollectorDefinition[];actions:string[];writeActions:boolean;manage:boolean;busy:boolean}>()
const emit=defineEmits<{(e:'update:busy',v:boolean):void;(e:'changed'):void}>()
const api=useApi(),auth=useAuth()
const path=`/connectors/targets/${props.target.id}` // keyed by target in parent
const tab=ref<'grants'|'runs'|'events'|'actions'|'plans'>('runs')
const plans=ref<CollectionJobPlan[]>([])
const planForm=reactive({name:'',collector:'',operation:'inspect',ttl:86400,kind:'interval',interval:300,cron:'*/5 * * * *',timezone:'UTC',jitter:0})
const planOps=computed(()=>allowedOps.value.filter(op=>op!=='health'))
const planCollectors=computed(()=>(props.collectors||[]).filter(c=>c.operations.includes(planForm.operation)))
const grants=ref<ServiceGrant[]>([]),runs=ref<ConnectorRun[]>([]),sources=ref<WebhookSource[]>([]),events=ref<ConnectorEvent[]>([]),actionRows=ref<ConnectorAction[]>([]),vms=ref<LifecycleResource[]>([])
const historyPlanId=ref('')
const offset=ref(0),more=ref(false),loading=ref(false),error=ref(''),message=ref(''),now=ref(Date.now())
const grantForm=reactive({operation:'sync',ttl:86400,scheduled:false,interval:300})
const collector=ref('')
const grantId=ref(''),syncGrantId=ref(''),password=ref(''),totp=ref(''),power=reactive({action:'vm.start',external:'',confirm:''}),ack=ref(''),selectedAction=ref<ConnectorAction|null>(null),selectedRun=ref<ConnectorRun|null>(null)
const oneTime=ref<{id:string;secret:string}|null>(null), revealSecret=ref(false)
const canGrants=computed(()=>auth.can('connectors.credentials.read'))
const canRuns=computed(()=>auth.can('inventory.assets.read')&&auth.can('connectors.targets.read'))
const canActions=computed(()=>auth.can('connectors.actions.read'))
const canDelegate=computed(()=>props.manage&&auth.can('vault.credentials.use')&&!!props.binding&&!!props.target.asset_id&&props.target.state==='active')
const allowedOps=computed(()=>props.operations.filter(op=>op==='health'||(op==='inspect'&&auth.can('inventory.assets.read'))||(op==='sync'&&auth.can('inventory.assets.create')&&auth.can('inventory.assets.update'))))
const canResolveAction=computed(()=>canDelegate.value&&auth.can('connectors.actions.execute')&&auth.can('inventory.assets.read')&&props.actions.length>0)
const canPower=computed(()=>canResolveAction.value&&props.writeActions)
const validGrants=computed(()=>grants.value.filter(g=>usableGrant(g,props.target,auth.user.value?.id||'',props.binding,now.value)))
const compatibleCollectors=computed(()=> (props.collectors||[]).filter(c=>c.operations.includes(validGrants.value.find(g=>g.id===grantId.value)?.operation||'')))
watch(grantId,()=>{collector.value=''})
const syncGrants=computed(()=>validGrants.value.filter(g=>g.operation==='sync'))
const mfaReady=computed(()=>!!password.value&&/^\d{6}$/.test(totp.value))
const tabs=computed(()=>[
  ...(canGrants.value?[{id:'grants' as const,label:'Разрешения и расписания'}]:[]),
  ...(canRuns.value?[{id:'plans' as const,label:'Планы сбора'},{id:'runs' as const,label:'Запуски'},{id:'events' as const,label:'Webhook и события'}]:[]),
  ...(canActions.value?[{id:'actions' as const,label:'Удалённые действия'}]:[]),
])
let disposed=false, mutating=false, sequence=0, timer:ReturnType<typeof setInterval>|undefined
const pendingKeys=new Map<string,string>()
function keyFor(scope:string){let key=pendingKeys.get(scope);if(!key){key=crypto.randomUUID();pendingKeys.set(scope,key)}return key}
function clearMfa(){password.value='';totp.value=''}
function clearSecret(){oneTime.value=null;revealSecret.value=false}
function fail(e:unknown){const problem=apiError(e);error.value=problem.message+(problem.code?` (${problem.code})`:'')+(problem.status===412?' — обновите конфигурацию и повторите подтверждение.':'')}
async function get<T>(suffix:string){return (await api.get<{data:T}>(path+suffix)).data}
async function refresh(background=false){
  if(disposed||loading.value||(!background&&props.busy))return
  const request=++sequence,current=tab.value,page=offset.value;loading.value=true
  try{
    if(canGrants.value&&['grants','runs','events'].includes(current)){
      const data=await get<ServiceGrant[]>('/service-grants');if(disposed||request!==sequence)return;grants.value=data
    }
    if(current==='plans'&&canRuns.value){const data=await get<CollectionJobPlan[]>(`/collection-plans?limit=50&offset=${page}`);if(disposed||request!==sequence)return;plans.value=data;more.value=data.length===50}
    if(current==='runs'&&canRuns.value){const data=await get<ConnectorRun[]>(`/runs?limit=50&offset=${page}${historyPlanId.value?`&plan_id=${encodeURIComponent(historyPlanId.value)}`:''}`);if(disposed||request!==sequence)return;const changed=data.some(r=>r.status==='succeeded'&&!runs.value.some(old=>old.id===r.id&&old.status===r.status));runs.value=data;more.value=data.length===50;if(changed)emit('changed')
      if(selectedRun.value){const id=selectedRun.value.id;const row=await get<ConnectorRun>(`/runs/${id}`);if(!disposed&&request===sequence&&selectedRun.value?.id===id)selectedRun.value=row}}
    if(current==='events'&&canRuns.value){const [s,e]=await Promise.all([get<WebhookSource[]>('/webhook-sources'),get<ConnectorEvent[]>(`/events?limit=50&offset=${page}`)]);if(disposed||request!==sequence)return;sources.value=s;events.value=e;more.value=e.length===50}
    if(current==='actions'&&canActions.value){const data=await get<ConnectorAction[]>(`/actions?offset=${page}`);if(disposed||request!==sequence)return;actionRows.value=data;more.value=data.length===50
      if(selectedAction.value){const id=selectedAction.value.id;const row=await get<ConnectorAction>(`/actions/${id}`);if(!disposed&&request===sequence&&selectedAction.value?.id===id)selectedAction.value=row}}
  }catch(e){if(!disposed&&request===sequence)fail(e)}finally{if(request===sequence)loading.value=false}
}
async function switchTab(next:typeof tab.value,planId=''){if(props.busy)return;sequence++;vmSequence++;loading.value=false;tab.value=next;historyPlanId.value=planId;offset.value=0;more.value=false;error.value='';message.value='';clearMfa();clearSecret();selectedRun.value=null;selectedAction.value=null;ack.value='';power.confirm='';await refresh();if(next==='actions')await loadVMs(0)}
async function pageBy(delta:number){if(loading.value||props.busy)return;offset.value=Math.max(0,Math.min(10000,offset.value+delta));await refresh()}
const vmOffset=ref(0),vmMore=ref(false);let vmSequence=0
async function loadVMs(page:number){if(!canRuns.value||!canPower.value)return;const req=++vmSequence;try{const rows=await get<LifecycleResource[]>(`/resources?limit=50&offset=${page}`);if(disposed||tab.value!=='actions'||req!==vmSequence)return;vms.value=rows.filter(canPowerResource);vmOffset.value=page;vmMore.value=rows.length===50;if(!vms.value.some(r=>r.external_id===power.external)){power.external='';power.confirm=''}}catch(e){if(!disposed)fail(e)}}
async function write<T>(method:'POST'|'DELETE',suffix:string,body?:unknown,headers:Record<string,string>={}){return (await api.write<{data:T}>(method,path+suffix,body,true,headers))?.data}
async function stepUp(){const b=props.binding,t=props.target;if(!b||!t.asset_id||!mfaReady.value)throw new Error('MFA required');const body={asset_id:t.asset_id,purpose:b.purpose,password:password.value,totp:totp.value};clearMfa();await api.write('POST',`/vault/credentials/${b.credential_id}/authorize-use`,body)}
async function mutate(fn:()=>Promise<void>){if(props.busy||mutating||disposed)return;mutating=true;emit('update:busy',true);sequence++;loading.value=false;error.value='';message.value='';try{await fn();if(!disposed){emit('changed');await refresh(true)}}catch(e){if(!disposed){fail(e);await refresh(true)}}finally{mutating=false;clearMfa();if(!disposed)emit('update:busy',false)}}
async function issue(){const etag=props.target.etag;if(!canDelegate.value||!mfaReady.value||!allowedOps.value.includes(grantForm.operation)||!grantLimits(grantForm.ttl,grantForm.scheduled?grantForm.interval:null))return;const body={operation:grantForm.operation,ttl_seconds:grantForm.ttl,...(grantForm.scheduled?{interval_seconds:grantForm.interval}:{})};await mutate(async()=>{await stepUp();const g=await write<ServiceGrant>('POST','/service-grants',body,{'If-Match':etag});grantId.value=g.id;message.value='Разрешение выдано. '+(grantForm.scheduled?'Расписание активировано.':'Можно поставить запуск в очередь.')})}
async function createPlan(){
  if(!canDelegate.value||!mfaReady.value||!planOps.value.includes(planForm.operation)||!planCollectors.value.some(c=>c.name===planForm.collector))return
  const body={name:planForm.name,collector:planForm.collector,operation:planForm.operation,ttl_seconds:planForm.ttl,jitter_seconds:planForm.jitter,...(planForm.kind==='interval'?{interval_seconds:planForm.interval}:{cron:planForm.cron,timezone:planForm.timezone})}
  const etag=props.target.etag
  await mutate(async()=>{await stepUp();await write<CollectionJobPlan>('POST','/collection-plans',body,{'If-Match':etag});offset.value=0;message.value='План создан.'})
}
async function changePlan(p:CollectionJobPlan){if(!props.manage)return;await mutate(async()=>{await write('POST',`/collection-plans/${p.id}/state`,{enabled:!p.enabled});message.value=p.enabled?'Расписание приостановлено.':'Расписание возобновлено.'})}
async function runPlan(id:string,redrive?:string){if(!props.manage)return;const scope=`plan:${id}:${redrive||'manual'}`;await mutate(async()=>{const r=await write<{id:string}>('POST',`/collection-plans/${id}/runs`,redrive?{redrive_of:redrive}:{},{'Idempotency-Key':keyFor(scope)});selectedRun.value=await get<ConnectorRun>(`/runs/${r.id}`);pendingKeys.delete(scope);tab.value='runs';historyPlanId.value=id;offset.value=0;message.value=`Запуск ${r.id} поставлен в очередь.`})}
function livePlan(p:CollectionJobPlan){return p.actor_id===auth.user.value?.id&&!p.revoked_at&&Date.parse(p.expires_at)>now.value}
async function revoke(g:ServiceGrant){if(!props.manage||!confirm('Отозвать разрешение и остановить дальнейшие запуски по нему?'))return;await mutate(async()=>{await write('DELETE',`/service-grants/${g.id}`);message.value='Разрешение отозвано.'})}
async function enqueue(){const g=validGrants.value.find(x=>x.id===grantId.value);if(!g||!props.manage)return;await mutate(async()=>{if(collector.value&&!compatibleCollectors.value.some(c=>c.name===collector.value))return;const scope=`run:${g.id}:${collector.value}`;const r=await write<{id:string;deduplicated:boolean}>('POST','/runs',{grant_id:g.id,...(collector.value?{collector:collector.value}:{})},{'Idempotency-Key':keyFor(scope)});selectedRun.value=await get<ConnectorRun>(`/runs/${r.id}`);pendingKeys.delete(scope);offset.value=0;message.value='Запуск поставлен в очередь.'})}
async function showRun(r:ConnectorRun){selectedRun.value=r;try{const row=await get<ConnectorRun>(`/runs/${r.id}`);if(!disposed&&selectedRun.value?.id===r.id)selectedRun.value=row}catch(e){fail(e)}}
async function cancelRun(r:ConnectorRun){if(!props.manage||!isRunPending(r.status)||!confirm('Отменить запуск?'))return;await mutate(async()=>{selectedRun.value=await write<ConnectorRun>('POST',`/runs/${r.id}/cancel`);message.value='Запрошена отмена запуска.'})}
async function createSource(){if(!props.manage||!syncGrants.value.some(g=>g.id===syncGrantId.value))return;clearSecret();await mutate(async()=>{oneTime.value=await write<WebhookSource&{secret:string}>('POST','/webhook-sources',{grant_id:syncGrantId.value});message.value='Источник создан. Сохраните ключ сейчас.'})}
async function changeSource(s:WebhookSource,rotate:boolean){if(!props.manage||s.revoked_at||!confirm(rotate?'Заменить ключ? Старый немедленно перестанет действовать.':'Отозвать источник и его незавершённые события?'))return;clearSecret();await mutate(async()=>{if(rotate){oneTime.value=await write<WebhookSource&{secret:string}>('POST',`/webhook-sources/${s.id}/rotate`);message.value='Ключ заменён. Сохраните новый ключ сейчас.'}else{await write('DELETE',`/webhook-sources/${s.id}`);message.value='Источник отозван.'}})}
async function redrive(e:ConnectorEvent){if(!props.manage||!canRedrive(e.status)||!syncGrants.value.some(g=>g.id===syncGrantId.value)||!confirm('Повторно поставить событие в очередь?'))return;await mutate(async()=>{await write('POST',`/events/${e.id}/redrive`,{grant_id:syncGrantId.value});message.value='Событие поставлено повторно.'})}
async function submitPower(){if(!canPower.value||!mfaReady.value||!props.actions.includes(power.action)||!vms.value.some(r=>r.external_id===power.external)||power.confirm!==actionConfirmation(power.action,power.external))return;const body={action:power.action,external_id:power.external,confirm:power.confirm},etag=props.target.etag;await mutate(async()=>{await stepUp();const scope=`power:${body.confirm}`;selectedAction.value=await write<ConnectorAction>('POST','/actions',body,{'If-Match':etag,'Idempotency-Key':keyFor(scope)});pendingKeys.delete(scope);power.confirm='';offset.value=0;message.value='Действие принято. Проверьте результат удалённой задачи.'})}
async function refreshAction(a:ConnectorAction,acknowledge=false){const etag=props.target.etag;if(!canResolveAction.value||!mfaReady.value||(!acknowledge&&!a.remote_task)||(acknowledge&&(!canAcknowledge(a.status)||ack.value!=='I verified the remote result')))return;await mutate(async()=>{await stepUp();selectedAction.value=await write<ConnectorAction>('POST',`/actions/${a.id}/${acknowledge?'acknowledge':'refresh'}`,acknowledge?{confirm:ack.value}:undefined,{'If-Match':etag});ack.value='';message.value='Состояние действия обновлено.'})}
watch(planOps,ops=>{if(ops.length&&!ops.includes(planForm.operation))planForm.operation=ops[0]!})
watch(planCollectors,items=>{if(!items.some(c=>c.name===planForm.collector))planForm.collector=''})
watch(allowedOps,ops=>{if(ops.length&&!ops.includes(grantForm.operation))grantForm.operation=ops[0]!})
watch(()=>props.binding?.credential_version,()=>{clearMfa();clearSecret();void refresh()})
watch(()=>props.target.version,()=>{clearMfa();clearSecret();power.confirm='';void refresh()})
watch(()=>power.external,()=>{power.confirm=''})
watch(()=>power.action,()=>{power.confirm=''})
onMounted(()=>{if(!tabs.value.some(t=>t.id===tab.value))tab.value=tabs.value[0]?.id||'runs';if(allowedOps.value.length&&!allowedOps.value.includes(grantForm.operation))grantForm.operation=allowedOps.value[0]!;void refresh();timer=setInterval(()=>{now.value=Date.now();if(!document.hidden&&!props.busy)void refresh(true)},5000)})
onBeforeUnmount(()=>{disposed=true;sequence++;if(timer)clearInterval(timer);clearMfa();clearSecret();pendingKeys.clear();vmSequence++})
</script>
<template>
  <section v-if="tabs.length" class="panel" data-testid="connector-lifecycle">
    <h2>Жизненный цикл: {{ target.name }}</h2>
    <div class="inline-actions" aria-label="Разделы коннектора"><button v-for="t in tabs" :key="t.id" type="button" class="btn" :class="{primary:tab===t.id}" :aria-pressed="tab===t.id" :disabled="busy" @click="switchTab(t.id)">{{t.label}}</button></div>
    <p v-if="error" class="alert" role="alert">{{error}}</p><p v-if="message" class="alert success" role="status">{{message}}</p>
    <div class="toolbar"><span class="muted small">Автообновление каждые 5 секунд. {{loading?'Загрузка…':''}}</span><button type="button" class="btn" :disabled="busy||loading" @click="refresh()">Обновить раздел</button></div>
    <template v-if="tab==='grants'">
      <h3>Сервисные разрешения</h3><p class="muted">Разрешение действует для одной операции и текущей версии подключения и credential. Изменение конфигурации или ротация требует нового разрешения. Расписание отключается отзывом разрешения.</p>
      <form v-if="canDelegate&&allowedOps.length" @submit.prevent="issue"><fieldset :disabled="busy">
        <div class="form-row"><label>Операция <select v-model="grantForm.operation" data-testid="grant-operation"><option v-for="op in allowedOps" :key="op" :value="op">{{op}}</option></select></label><label>Срок действия (секунды)<input v-model.number="grantForm.ttl" type="number" min="60" max="2592000" required data-testid="grant-ttl" /></label></div>
        <label><input v-model="grantForm.scheduled" type="checkbox" data-testid="grant-scheduled" /> Автоматическое расписание</label><label v-if="grantForm.scheduled">Интервал (секунды)<input v-model.number="grantForm.interval" type="number" min="60" max="86400" required data-testid="grant-interval" /></label>
        <div class="form-row"><label>Пароль для MFA<input v-model="password" type="password" autocomplete="off" required data-testid="lifecycle-password" /></label><label>TOTP<input v-model="totp" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" required data-testid="lifecycle-totp" /></label></div>
        <button class="btn primary" :disabled="busy||!mfaReady||!grantLimits(grantForm.ttl,grantForm.scheduled?grantForm.interval:null)">Выдать разрешение</button></fieldset>
      </form>
      <p v-else class="muted">Для выдачи необходимо активное подключение, привязанный Vault credential и разрешённая операция.</p>
      <div class="table-wrap"><table class="table"><thead><tr><th>Разрешение / операция</th><th>Срок / состояние</th><th>Расписание</th><th>Действия</th></tr></thead><tbody><tr v-for="g in grants" :key="g.id"><td class="mono">{{g.id}}<br>{{g.operation}}</td><td>{{g.expires_at}}<br>{{g.revoked_at?'Отозвано':Date.parse(g.expires_at)<=now?'Истекло':Number(g.target_version)!==target.version||(binding&&Number(g.credential_version)!==Number(binding.credential_version))?'Устарело':'Выдано'}}</td><td>{{g.collection_plan_id?'План сбора':g.interval_seconds?`${g.interval_seconds} с`:'Ручное'}}<br>{{g.next_due_at||'—'}}</td><td><button v-if="manage&&!g.revoked_at" class="btn danger" type="button" :disabled="busy" @click="revoke(g)">Отозвать разрешение</button></td></tr></tbody></table></div><p v-if="!grants.length" class="muted">Разрешений нет.</p>
    </template>
    <template v-else-if="tab==='plans'">
      <h3>Постоянные планы сбора</h3><p class="muted">Пауза отключает расписание, но не отменяет уже принятые задания. Отзыв разрешения останавливает их применение. Для изменения параметров или продления срока создайте новый план.</p>
      <form v-if="canDelegate&&planOps.length" @submit.prevent="createPlan"><fieldset :disabled="busy">
        <label>Название<input v-model="planForm.name" maxlength="120" required /></label>
        <label>Операция<select v-model="planForm.operation"><option v-for="op in planOps" :key="op" :value="op">{{op}}</option></select></label>
        <label>Коллектор<select v-model="planForm.collector" required><option value="">Выберите коллектор</option><option v-for="c in planCollectors" :key="c.name" :value="c.name">{{c.name}}</option></select></label>
        <label>Срок разрешения (секунды)<input v-model.number="planForm.ttl" type="number" min="60" max="2592000" required /></label>
        <label>Сдвиг запуска (секунды, 0–30)<input v-model.number="planForm.jitter" type="number" min="0" max="30" required /></label>
        <label>Расписание<select v-model="planForm.kind"><option value="interval">Интервал</option><option value="cron">Cron</option></select></label>
        <label v-if="planForm.kind==='interval'">Интервал (секунды)<input v-model.number="planForm.interval" type="number" min="60" max="86400" required /></label>
        <template v-else><label>Cron (5 полей)<input v-model="planForm.cron" required maxlength="120" /></label><label>Часовой пояс IANA<input v-model="planForm.timezone" required maxlength="64" /></label></template>
        <div class="form-row"><label>Пароль для MFA<input v-model="password" type="password" autocomplete="off" required /></label><label>TOTP<input v-model="totp" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" required /></label></div>
        <button class="btn primary" :disabled="busy||!mfaReady||!planCollectors.some(c=>c.name===planForm.collector)">Создать план</button>
      </fieldset></form>
      <div class="table-wrap"><table class="table"><thead><tr><th>План</th><th>Расписание</th><th>Разрешение</th><th>Действия</th></tr></thead><tbody><tr v-for="p in plans" :key="p.id"><td>{{p.name}}<br>{{p.collector_name}} · {{p.operation}}</td><td>{{p.interval_seconds?`${p.interval_seconds} с`:`${p.cron_expression} (${p.timezone})`}}<br>{{p.enabled?'Следующий: '+p.next_due_at:'Пауза'}}</td><td>{{p.expires_at}}<br>{{p.revoked_at?'Отозвано':Date.parse(p.expires_at)<=now?'Истекло':'Действует'}}</td><td><button type="button" class="btn" :disabled="busy" @click="switchTab('runs',p.id)">История</button><button v-if="manage&&(p.enabled||livePlan(p))" type="button" class="btn" :disabled="busy" @click="changePlan(p)">{{p.enabled?'Пауза':'Возобновить'}}</button><button v-if="manage&&livePlan(p)" type="button" class="btn" :disabled="busy" @click="runPlan(p.id)">Запустить</button></td></tr></tbody></table></div>
      <p v-if="!plans.length" class="muted">Планов нет.</p>
    </template>
    <template v-else-if="tab==='runs'">
      <h3>Фоновые запуски</h3><p v-if="historyPlanId" class="muted">План: {{historyPlanId}} <button type="button" class="btn" @click="switchTab('runs')">Все запуски</button></p><form v-if="manage&&canGrants" @submit.prevent="enqueue"><label>Сервисное разрешение<select v-model="grantId" data-testid="run-grant"><option value="">Выберите разрешение</option><option v-for="g in validGrants" :key="g.id" :value="g.id">{{g.operation}} — {{g.id}}</option></select></label><label>Коллектор<select v-model="collector" data-testid="run-collector"><option value="">Обычная операция</option><option v-for="c in compatibleCollectors" :key="c.name" :value="c.name">{{c.name}}</option></select></label><button class="btn primary" :disabled="busy||!validGrants.some(g=>g.id===grantId)||(!!collector&&!compatibleCollectors.some(c=>c.name===collector))">Поставить в очередь</button></form>
      <div class="table-wrap"><table class="table"><thead><tr><th>Запуск</th><th>Статус</th><th>Попытки / ошибка</th><th>Действия</th></tr></thead><tbody><tr v-for="r in runs" :key="r.id" :data-testid="`run-${r.id}`"><td class="mono">{{r.id}}<br>{{r.operation}} · {{r.collector_name||'обычная операция'}} · {{r.created_at}}</td><td>{{r.status}}</td><td>{{r.attempts}} / {{r.error_code||'—'}}</td><td><button class="btn" type="button" @click="showRun(r)">Результат</button><button v-if="manage&&isRunPending(r.status)" class="btn danger" type="button" :disabled="busy" @click="cancelRun(r)">Отменить запуск</button></td></tr></tbody></table></div><p v-if="!runs.length" class="muted">Запусков нет.</p>
      <section v-if="selectedRun" class="panel" data-testid="run-detail"><h3>Результат запуска</h3><p class="mono">{{selectedRun.id}} — {{selectedRun.status}}</p><p>{{selectedRun.error_code||''}}</p><p v-if="selectedRun.collection_plan_id">План: {{selectedRun.collection_plan_id}}</p><p v-if="selectedRun.redrive_of">Повтор: {{selectedRun.redrive_of}}</p><div v-if="selectedRun.attempt_history?.length" class="table-wrap"><table class="table"><thead><tr><th>Попытка</th><th>Начало</th><th>Результат</th></tr></thead><tbody><tr v-for="a in selectedRun.attempt_history" :key="a.attempt"><td>{{a.attempt}}</td><td>{{a.started_at}}</td><td>{{a.outcome}} {{a.error_code||''}}</td></tr></tbody></table></div><button v-if="manage&&selectedRun.collection_plan_id&&['failed','cancelled'].includes(selectedRun.status)" type="button" class="btn" :disabled="busy" @click="runPlan(selectedRun.collection_plan_id||'',selectedRun.id)">Повторить сбор</button><pre>{{JSON.stringify(selectedRun.result,null,2)}}</pre><button type="button" class="btn" @click="selectedRun=null">Закрыть результат</button></section>
    </template>
    <template v-else-if="tab==='events'">
      <h3>Подписанные источники</h3><p class="muted">Источники используют действующий sync grant. Подпись HMAC-SHA256; события запускают повторное чтение удалённого API.</p>
      <form v-if="manage&&canGrants" @submit.prevent="createSource"><label>Sync-разрешение<select v-model="syncGrantId" data-testid="webhook-grant"><option value="">Выберите разрешение</option><option v-for="g in syncGrants" :key="g.id" :value="g.id">{{g.id}}</option></select></label><button class="btn primary" :disabled="busy||!syncGrants.some(g=>g.id===syncGrantId)">Создать источник</button></form>
      <section v-if="oneTime" class="panel" data-testid="webhook-one-time"><h3>Одноразовый ключ подписи</h3><p>Сохраните ключ в защищённом хранилище отправителя. После закрытия он недоступен.</p><label>Endpoint<input readonly :value="`/api/v1/connectors/webhooks/${oneTime.id}/events`" /></label><label>Ключ<input readonly :type="revealSecret?'text':'password'" :value="oneTime.secret" data-testid="webhook-secret" autocomplete="off" /></label><button class="btn" type="button" @click="revealSecret=!revealSecret">{{revealSecret?'Скрыть значение':'Показать значение'}}</button> <button class="btn" type="button" @click="clearSecret">Закрыть ключ</button><p class="small muted">Выделите значение поля и скопируйте его в хранилище.</p></section>
      <div class="table-wrap"><table class="table"><thead><tr><th>Источник</th><th>Версия ключа</th><th>Состояние</th><th>Действия</th></tr></thead><tbody><tr v-for="s in sources" :key="s.id"><td class="mono">{{s.id}}<br>grant: {{s.grant_id}}</td><td>{{s.key_version}}</td><td>{{s.revoked_at?'Отозван':'Активен'}}</td><td><template v-if="manage&&!s.revoked_at"><button v-if="syncGrants.some(g=>g.id===s.grant_id)" class="btn" type="button" :disabled="busy" @click="changeSource(s,true)">Ротировать ключ</button><button class="btn danger" type="button" :disabled="busy" @click="changeSource(s,false)">Отозвать источник</button></template></td></tr></tbody></table></div>
      <h3>События и dead letter</h3><div class="table-wrap"><table class="table"><thead><tr><th>Событие</th><th>Статус / ошибка</th><th>Запуски</th><th>Действие</th></tr></thead><tbody><tr v-for="e in events" :key="e.id"><td class="mono">{{e.event_id}}<br>{{e.event_type}} · {{e.resource_id||'—'}}</td><td>{{e.status}}<br>{{e.error_code||'—'}}</td><td><details><summary>{{e.dispatch_count}} запуск(ов)</summary><p v-for="d in e.dispatches" :key="d.run_id" class="mono">{{d.run_id}} · {{d.dispatched_at}}</p></details></td><td><button v-if="manage&&canRedrive(e.status)" class="btn" type="button" :disabled="busy||!syncGrants.some(g=>g.id===syncGrantId)" @click="redrive(e)">Повторить событие</button></td></tr></tbody></table></div><p v-if="!events.length" class="muted">Событий нет.</p>
    </template>
    <template v-else-if="tab==='actions'">
      <h3>Удалённые действия</h3><p class="muted">Запуск и выключение QEMU VM требуют отдельного права и свежего MFA. Не повторяйте неизвестный результат: сначала проверьте Proxmox. Статус submitted не означает завершение.</p>
      <p v-if="!writeActions" class="alert info">Удалённые изменяющие действия отключены на сервере.</p>
      <fieldset v-if="canResolveAction" :disabled="busy"><legend>MFA для действий и проверки результата</legend><div class="form-row"><label>Пароль для MFA<input v-model="password" type="password" autocomplete="off" required data-testid="lifecycle-password" /></label><label>TOTP<input v-model="totp" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" required data-testid="lifecycle-totp" /></label></div></fieldset>
      <template v-if="canPower"><div class="form-row"><label>Действие<select v-model="power.action"><option v-for="a in props.actions" :key="a" :value="a">{{a}}</option></select></label><label>Обнаруженная VM<select v-model="power.external" data-testid="power-resource"><option value="">Выберите VM</option><option v-for="r in vms" :key="r.external_id" :value="r.external_id">{{r.external_id}}</option></select></label></div><div class="inline-actions"><button class="btn" type="button" :disabled="busy||vmOffset===0" @click="loadVMs(vmOffset-50)">Предыдущие ресурсы</button><button class="btn" type="button" :disabled="busy||!vmMore||vmOffset>=10000" @click="loadVMs(vmOffset+50)">Следующие ресурсы</button><button class="btn" type="button" :disabled="busy" @click="loadVMs(vmOffset)">Обновить VM</button></div><form @submit.prevent="submitPower"><fieldset :disabled="busy"><label>Введите точно: {{actionConfirmation(power.action,power.external)}}<input v-model="power.confirm" autocomplete="off" required data-testid="power-confirm" /></label><button class="btn danger" :disabled="busy||!mfaReady||!power.external||power.confirm!==actionConfirmation(power.action,power.external)">Выполнить действие</button></fieldset></form></template>
      <div class="table-wrap"><table class="table"><thead><tr><th>Действие</th><th>Статус</th><th>Удалённая задача</th><th>Детали</th></tr></thead><tbody><tr v-for="a in actionRows" :key="a.id"><td>{{a.action}} {{a.external_id}}<br>{{a.created_at}}</td><td>{{a.status}}<br>{{a.error_code||''}}</td><td class="mono">{{a.remote_task||'—'}}</td><td><button class="btn" type="button" :disabled="busy" @click="selectedAction=a;ack='';clearMfa()">Подробнее</button></td></tr></tbody></table></div><p v-if="!actionRows.length" class="muted">Действий нет.</p>
      <section v-if="selectedAction" class="panel" data-testid="action-detail"><h3>Результат действия</h3><p class="mono">{{selectedAction.id}} · {{selectedAction.action}} {{selectedAction.external_id}} · {{selectedAction.status}}</p><p class="mono">{{selectedAction.remote_task||'UPID отсутствует'}} · {{selectedAction.error_code||'—'}}</p><template v-if="canResolveAction"><button v-if="selectedAction.remote_task&&selectedAction.status==='submitted'" class="btn" type="button" :disabled="busy||!mfaReady" @click="refreshAction(selectedAction)">Проверить удалённую задачу</button><template v-if="canAcknowledge(selectedAction.status)"><label>После ручной проверки в Proxmox введите I verified the remote result<input v-model="ack" autocomplete="off" /></label><button class="btn danger" type="button" :disabled="busy||!mfaReady||ack!=='I verified the remote result'" @click="refreshAction(selectedAction,true)">Подтвердить проверку</button></template></template><button class="btn" type="button" @click="selectedAction=null;ack=''">Закрыть действие</button></section>
    </template>
    <div v-if="tab!=='grants'" class="inline-actions"><button class="btn" type="button" :disabled="busy||loading||offset===0" @click="pageBy(-50)">Предыдущая страница</button><span class="muted">Страница {{offset/50+1}}</span><button class="btn" type="button" :disabled="busy||loading||!more||offset>=10000" @click="pageBy(50)">Следующая страница</button></div>
  </section>
</template>
